--   回退脚本:把「生产工单明细表 MANU_ORDER_DETAIL / 生产工单统计表 MANU_ORDER_STATS」原样插回 HSDZ_MES_TEST
--   由 tools/archive/_gen-manu-order-panels-restore.mjs 连库现读生成(视图定义= sys.sql_modules;元数据= 逐列取值)
--   用法: 先确认库名,再整份执行;幂等(已存在则跳过)。
--   生成时间: 2026-10-16T03:02:44.830Z
SET NOCOUNT ON;
GO
PRINT N'[库] ' + DB_NAME() + N' — 回退 生产工单明细表/统计表';
GO
IF OBJECT_ID('dbo.v_manu_order_detail','V') IS NULL
EXEC(N'CREATE VIEW v_manu_order_detail AS SELECT h.[合同号] AS [单据编号], h.*, l.[产品编码], l.[存货图片], l.[产品名称], l.[规格型号], l.[型号], l.[生产单位], l.[数量], l.[齐套数量(主)], l.[累计汇报套数(工序单位)], l.[可用量], l.[现存量], l.[图号], l.[单重], l.[总重], l.[需求令号] FROM bd_manu_order h LEFT JOIN bl_manu_order l ON h.[合同号]=l.[合同号]');
ELSE PRINT N'[视图] v_manu_order_detail 已存在(跳过)';
GO
IF OBJECT_ID('dbo.v_manu_order_stats','V') IS NULL
EXEC(N'CREATE   VIEW v_manu_order_stats AS
SELECT ROW_NUMBER() OVER(ORDER BY (SELECT NULL)) AS id, h.asp_cancel,
       l.[产品编码], l.[产品名称], l.[规格型号], l.[生产单位],
       COUNT(DISTINCT h.[合同号]) AS [加工单数],
       SUM(COALESCE(l.[数量],0)) AS [计划数量],
       SUM(COALESCE(l.[累计汇报套数(工序单位)],0)) AS [累计汇报数量],
       SUM(CASE WHEN h.[完工日期] IS NOT NULL THEN COALESCE(l.[数量],0) ELSE 0 END) AS [完工数量],
       CAST(ISNULL(100.0*SUM(COALESCE(l.[累计汇报套数(工序单位)],0))/NULLIF(SUM(COALESCE(l.[数量],0)),0),0) AS decimal(18,2)) AS [生产进度%]
FROM bd_manu_order h
LEFT JOIN bl_manu_order l ON h.[合同号] = l.[合同号]
WHERE NOT EXISTS (SELECT 1 FROM yj_doc_status s WHERE s.panel_code = ''MANU_ORDER''
                    AND s.doc_no = h.[合同号] AND s.canceled = ''Y'')
GROUP BY h.asp_cancel, l.[产品编码], l.[产品名称], l.[规格型号], l.[生产单位]');
ELSE PRINT N'[视图] v_manu_order_stats 已存在(跳过)';
GO
